export type AppClientRouteAuth = 'required' | 'guest' | 'optional';
/**
 * Authorization checked before this page loads. `skip` opts out and does not
 * bypass parent guards; `unrestricted` admits only identities with unrestricted
 * access, such as root, and is never offered as a grant. A page that omits it
 * inherits its nearest ancestor page's value; the first page on a path defaults
 * to `unrestricted` on protected app and settings pages and to `skip` on guest,
 * optional and dev pages.
 */
export type AppClientRouteAuthz = 'skip' | 'unrestricted' | {
    readonly resource: {
        readonly type: string;
        readonly id: string;
    };
    readonly action: string;
};

function normalizeRouteAuthz(route, id, path, isPage, auth, context) {
    if ('access' in route) {
        throw new Error(`Client route "${id}" uses removed access; declare authz instead.`);
    }
    const value = 'authz' in route ? route.authz : undefined;
    if (value !== undefined) {
        if (!isPage)
            throw new Error(`Client route group "${id}" cannot declare authz.`);
        if (value === 'skip' || value === 'unrestricted')
            return value;
        if (!value ||
            typeof value !== 'object' ||
            !('resource' in value) ||
            !value.resource ||
            typeof value.resource !== 'object' ||
            typeof value.resource.type !== 'string' ||
            !value.resource.type.trim() ||
            typeof value.resource.id !== 'string' ||
            !value.resource.id.trim() ||
            typeof value.action !== 'string' ||
            !value.action.trim())
            throw new Error(`Client route "${id}" must use authz "skip", "unrestricted" or { resource: { type, id }, action }.`);
        return Object.freeze({
            resource: Object.freeze({ ...value.resource }),
            action: value.action,
        });
    }
    if (!isPage)
        return 'skip';
    if (context.ancestorAuthz !== undefined)
        return context.ancestorAuthz;
    // An omission never stops the application: a protected page stays closed to all but unrestricted identities.
    const fallback = context.surface === 'dev' ||
        (context.surface === 'app' && auth !== 'required')
        ? 'skip'
        : 'unrestricted';
    if (isDevelopment())
        console.warn(`Client route "${id}" at "${path}" does not declare authz; using "${fallback}". Declare authz on this page: { resource: { type, id }, action } or "skip".`);

/**
 * Record access keys, named once so the grants, the restriction rule and the
 * tests all spell them the same way.
 */
export const LIBRARY_RECORD_ACCESS = {
  /** Published and not confidential: every reader may open these. */
  readable: 'library.readable',
  /** Not confidential, whatever its published state. */
  nonConfidential: 'library.nonConfidential',
  /** The owner's own rows plus every readable row. */
  visible: 'library.visible',
  /**
   * The one record a temporary share points at.
   *
   * The authorization package's `records` selection carries string ids only,
   * and this table's primary key is an integer, so a `records` selection would
   * be rejected by the repository's filter validation. Naming the id in a
   * record access lets the resolver hand back a real number instead.
   */
  sharedDocument: 'library.sharedDocument',
} as const;

/** The params the `sharedDocument` record access reads. */
export interface SharedDocumentParams {
  readonly documentId?: unknown;
}

/**
 * The AND fold of the authorization package's internal `allScopes`.
 *
 * That helper is not part of the package's public surface, so the fold is
 * repeated here rather than reaching through a private subpath. `true` drops
 * out, `false` wins, and a single node collapses to itself.
 */
export function allScopes(scopes: readonly DatabaseScope[]): DatabaseScope {
  if (scopes.includes(false)) return false;
  const items = scopes.filter(
    (scope): scope is FilterNode => scope !== true && scope !== false,
  );
  if (items.length === 0) return true;
  return items.length === 1 ? items[0] : group('and', items);
}

/**
 * Exactly the one row a temporary share named.
 *
 * A missing, malformed or fractional id resolves to `false` rather than to a
 * filter the repository would refuse, so a broken share denies instead of
 * failing the request.
 */
export function sharedDocumentScope(documentId: unknown): DatabaseScope {
  const parsed =
    typeof documentId === 'number' ? documentId : Number(documentId);
  if (!Number.isSafeInteger(parsed)) return false;
  return condition('id', '$eq', parsed);
}

/** Turns a scope or field rejection from the repository into an HTTP-shaped error. */
function translateRepositoryError(error: unknown): LibraryError {
  const code = repositoryErrorCode(error);
  if (code === undefined || !code.endsWith('_FORBIDDEN')) {
    if (code === 'RECORD_NOT_FOUND' || code === 'RECORD_OUTSIDE_SCOPE') {
      return new LibraryError('DOCUMENT_NOT_FOUND', 'Document not found', 404);
    }
    return new LibraryError(
      'LIBRARY_WRITE_FAILED',
      error instanceof Error ? error.message : 'The operation failed',
      400,
    );
  }
  return new LibraryError(
    'LIBRARY_FORBIDDEN',
    'This account may not perform that operation',
    403,
  );
}

